from pathlib import Path
import json
from site_renderer import ROOT,e,photo,CAT
DATA=json.loads((ROOT/'data/faq-expanded.json').read_text(encoding='utf-8'))
CATALOG=[
("Sports Water Bottles","/collections/sports-water-bottles/","/media/ppt/slide-049.webp"),
("Kids Water Bottles","/collections/kids-water-bottles/","/media/ppt/slide-030.webp"),
("Large Capacity Water Jugs","/collections/large-capacity-water-jugs/","/media/ppt/slide-055.webp"),
("Protein Shaker Bottles","/collections/plastic-shaker-bottles/","/media/ppt/slide-091.webp")
]
LINKS=[
("About XUYI","/about/"),("Why Us","/why-us/"),("OEM / ODM","/capabilities/oem-odm/"),
("Manufacturing","/manufacturing/"),("Quality Control","/quality-control/"),
("Shipping & Logistics","/shipping-logistics/"),("Request a Sample","/request-sample/"),("FAQ","/faq/")
]
def photo_block(url,alt,caption=None):
 return '<figure class="rs-photo">'+photo(url,alt)+('<figcaption>'+e(caption)+'</figcaption>' if caption else '')+'</figure>'
def breadcrumb(title):
 return '<nav class="rs-crumb" aria-label="Breadcrumb"><a href="/">Home</a><span>/</span><span>'+e(title)+'</span></nav>'
def hero(title,answer,eyebrow,photo_url,alt,theme='white',caption=None):
 return '<section class="rs-hero rs-hero--'+theme+'"><div class="shell">'+breadcrumb(title)+'<div class="rs-hero__grid"><div class="rs-hero__copy"><span class="eyebrow">'+e(eyebrow)+'</span><h1>'+e(title)+'</h1><p>'+e(answer)+'</p><div class="rs-hero__actions"><a class="button" href="/contact/#inquiry">Discuss a Project →</a><a class="button button--outline" href="/products/">Explore Product Models →</a></div></div>'+photo_block(photo_url,alt,caption)+'</div></div></section>'
def heading(kicker,title,description=''):
 return '<div class="rs-heading"><span class="eyebrow">'+e(kicker)+'</span><h2>'+e(title)+'</h2>'+('<p>'+e(description)+'</p>' if description else '')+'</div>'
def grid_links(items):
 return '<div class="rs-links">'+''.join('<a href="'+e(uri)+'"><span>'+e(name)+'</span><b aria-hidden="true">↗</b></a>' for name,uri in items)+'</div>'
def product_grid():
 return '<div class="rs-products">'+''.join('<a href="'+url+'"><div>'+photo(image,name+' — original XUYI plastic catalog photo')+'</div><strong>'+e(name)+'</strong><span>Explore products ↗</span></a>' for name,url,image in CATALOG)+'</div>'
def question_groups(groups):
 return ''.join('<section class="rs-faq__group" id="'+cat["id"]+'" data-faq-group><header class="rs-faq__group-head"><span class="rs-faq__index">'+cat["icon"]+'</span><div><h2>'+e(cat["name"])+'</h2><p>'+e(cat["summary"])+'</p></div></header><div class="rs-faq__items">'+''.join('<details data-faq-item><summary>'+e(q)+'</summary><div class="rs-faq__answer"><p>'+e(a)+'</p><a href="'+e(link)+'">Related guide or service ↗</a></div></details>' for q,a,link in cat['questions'])+'</div></section>' for cat in groups)
def schema_add(html,key,description,faq_groups=None):
 url='https://xuyibottles.com/'+key+'/'
 org='https://xuyibottles.com/#organization'
 pages=[
  {'@type':'Organization','@id':org,'name':'XUYI Bottles','legalName':'台州市旭一家居用品有限公司','alternateName':'Taizhou Xuyi Household Goods Co., Ltd.','url':'https://xuyibottles.com/','address':{'@type':'PostalAddress','addressLocality':'Taizhou','addressRegion':'Zhejiang','addressCountry':'CN'}},
  {'@type':'WebPage','@id':url+'#webpage','url':url,'name':key.replace('-',' ').title()+' | XUYI Bottles','description':description,'inLanguage':'en','about':{'@id':org}},
  {'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Home','item':'https://xuyibottles.com/'},{'@type':'ListItem','position':2,'name':key.replace('-',' ').title(),'item':url}]}
 ]
 if faq_groups:
  allq=[(q,a) for c in faq_groups for q,a,_ in c['questions']]
  pages.append({'@type':'FAQPage','@id':url+'#faq','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}} for q,a in allq]})
 from organization_source_schema import enrich_organization
 pages=[enrich_organization(node) for node in pages]
 script='<script type="application/ld+json">'+json.dumps({'@context':'https://schema.org','@graph':pages},ensure_ascii=False,separators=(',',':')).replace('<','\\u003c')+'</script>'
 addition='<link rel="stylesheet" href="/assets/resource-pages.css"><script defer src="/assets/resource-pages.js"></script>'+script
 if key=='about':addition='<link rel="stylesheet" href="/assets/about-company.css">'+addition
 return html.replace('</head>',addition+'</head>',1)
def footer_cta(title,copy):
 return '<section class="rs-footer-cta"><div class="shell"><span class="eyebrow">PLASTIC WATER BOTTLE SOURCING</span><h2>'+e(title)+'</h2><p>'+e(copy)+'</p><a class="button" href="/contact/#inquiry">Prepare a Project Enquiry →</a></div></section>'
def faq_page():
 categories=DATA['categories']
 answer="Find practical, specific answers to sourcing plastic sports bottles, kids' bottles, large-capacity jugs and shakers. Use the sections to compare bulk buying, customization, material claims, samples, factory quality and international delivery."
 count=sum(len(c['questions']) for c in categories)
 s=hero('Plastic Water Bottle Wholesale FAQs',answer,'BUYER KNOWLEDGE CENTER · 7 PROCUREMENT TOPICS','/media/ppt/slide-037.webp','XUYI plastic sport bottle and kids bottle assortment',caption='Original XUYI plastic drinkware source catalog photography')
 s+='<section class="rs-faq__overview"><div class="shell"><div class="rs-faq__stats"><div><strong>'+str(count)+'</strong><span>Original buyer answers</span></div><div><strong>'+str(len(categories))+'</strong><span>Procurement topics</span></div><div><strong>4</strong><span>Plastic product families</span></div></div></div></section>'
 s+='<section class="rs-faq__search-band" id="questions"><div class="shell"><div class="rs-faq__search"><div class="rs-faq__search-intro"><span class="eyebrow">FIND AN ANSWER</span><h2>What would you like to know?</h2><p>Search by model, material, branding, order or shipping topic.</p></div><div class="rs-faq__search-tools"><label for="faq-search">Search our '+str(count)+' buyer questions</label><div class="rs-faq__search-field"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"></circle><path d="m16 16 5 5"></path></svg><input type="search" id="faq-search" placeholder="e.g. MOQ, logo printing, materials, samples, shipping" autocomplete="off" aria-controls="faq-groups"><button type="button" id="faq-reset" hidden>Clear ×</button></div><div class="rs-faq__search-meta"><p id="faq-results" role="status" aria-live="polite">Browse all '+str(count)+' questions below.</p><div class="rs-faq__suggestions" aria-label="Suggested FAQ searches"><span>Popular:</span>'+''.join('<button type="button" data-faq-suggest="'+e(term)+'">'+e(term)+'</button>' for term in ['MOQ','Materials','Logo','Sample','Shipping'])+'</div></div></div></div></div></section>'
 s+='<section class="rs-faq__main"><div class="shell"><div class="rs-faq__layout"><aside class="rs-faq__nav" aria-label="Question categories"><strong>JUMP TO A TOPIC</strong>'+''.join('<a href="#'+c['id']+'"><span>'+c['icon']+'</span>'+e(c['name'])+'</a>' for c in categories)+'</aside><div class="rs-faq__content" id="faq-groups">'+question_groups(categories)+'</div></div></div></section>'
 s+='<section class="rs-section rs-section--soft"><div class="shell">'+heading('HOW WE SUPPORT ORDERS','Packing, Quality & Dispatch','A practical look at bottle order preparation, inspection equipment and warehouse organization.')+'<div class="rs-proofline">'+photo_block('/media/group/factory-bottle-packing.webp','Team handling bottle packing crates','Order packing')+photo_block('/media/group/qa-color-box.webp','Color assessment light box for product and decoration inspection','Color inspection')+photo_block('/media/group/factory-shipment.webp','Racked cartons and products arranged for dispatch','Order storage and dispatch')+'</div></div></section>'
 s+='<section class="rs-section"><div class="shell">'+heading('BUYER RESOURCES','Explore the Four Bottle Collections')+product_grid()+heading('SERVICE GUIDE','Continue to the Right Resource')+grid_links(LINKS)+'</div></section>'
 return s+footer_cta('Have a Bottle Question Not Covered Here?','Share your bottle photo or model, quantity and sales country so the requirements can be reviewed model by model.')
