def why_us_page():
 s=hero('Why Buyers Work With XUYI','XUYI combines plastic drinkware model selection with an organized B2B workflow for artwork, sampling, component checking, packing and shipment. We guide product selection, sample approval, quality requirements and order coordination.','OUR APPROACH · PRACTICAL FACTORY-BACKED SOURCING','/media/ppt/slide-037.webp','XUYI original assortment of plastic water bottles',caption='Source catalog photography')
