 s+='<section class="rs-section"><div class="shell">'+heading('BUYER-FIRST SOURCING','Different Buyers Need Different Evidence','We start with the use case, not a generic promise of lowest price or unrestricted customization.')+'<div class="rs-why__buyers">'+''.join('<article><h3>'+e(title)+'</h3><p>'+e(text)+'</p><a href="'+url+'">Read related guidance ↗</a></article>' for title,text,url in buyer)+'</div></div></section>'
