 checks=[('Before quote','Model + quantity + country + available options'),('Before sample','Drawing, artwork, material list and intended use'),('Before production','Approved sample, revision and inspection criteria'),('Before shipping','Final counts, carton spec, agreed terms and documents')]
 s+='<section class="rs-section rs-section--dark"><div class="shell">'+heading('PROJECT CONTROL','Four Sign-offs Worth Having in Writing','Practical documented checkpoints help keep the order details clear.')+'<div class="rs-why__signoffs">'+''.join('<div><span>'+e(a)+'</span><p>'+e(b)+'</p></div>' for a,b in checks)+'</div></div></section>'
 s+='<section class="rs-section"><div class="shell">'+heading('CHOOSE YOUR NEXT STEP','See the Relevant Product or Service')+grid_links(LINKS)+product_grid()+'</div></section>'
