def sample_page():
 s=hero('Request a Plastic Water Bottle Sample','Use a sample to check the actual bottle shape, capacity, lid function, color and branding before committing to a larger order. Existing catalog references, decorated samples and new-tooling prototypes involve different checks and schedules.','SAMPLE PROGRAM · WHOLESALE & OEM','/media/ppt/slide-059.webp','Large plastic sports water bottle from XUYI catalog',caption='Original XUYI source catalog photo')
 steps=[('01','Choose an identifiable model','Provide product code or clear catalog image, target capacity and required cap style.'),('02','Send the brief','Include quantities, country, print artwork, body/lid colors and packing idea.'),('03','Review a rendering where needed','Structural and decorative concepts may need artwork, drawings or revised technical review.'),('04','Confirm sample arrangements','Agree whether a stock sample, decorated sample or prototype is feasible, with fee and schedule.'),('05','Evaluate the physical bottle','Check dimensional fit, drinking function, seal, print, colors and pack.'),('06','Approve the order reference','Document changes, verified material, test criteria, labels and carton configuration.')]
 s+='<section class="rs-section"><div class="shell">'+heading('SIX-STEP SAMPLE PROCESS','From Catalog Choice to an Approved Reference','Adapted to plastic drinkware and a model-specific approval process; exact fees and timing require confirmation.')+'<div class="rs-sample__timeline">'+''.join('<article><span>'+n+'</span><div><h3>'+e(t)+'</h3><p>'+e(d)+'</p></div></article>' for n,t,d in steps)+'</div></div></section>'
 s+='<section class="rs-section rs-section--soft"><div class="shell">'+heading('CHOOSE THE CORRECT SAMPLE','Stock Reference vs. Decorated Sample vs. Prototype')+'<div class="rs-sample__variants">'+''.join('<article><h3>'+e(a)+'</h3><p>'+e(b)+'</p><strong>'+e(c)+'</strong></article>' for a,b,c in [('Catalog reference','Assess basic body and lid ergonomics, approximate capacity and construction.','Does not approve custom artwork.'),('Branded confirmation sample','Review printed art, color appearance and intended packaging for the selected model.','Verify decoration on the real substrate.'),('New-design prototype','Evaluate proposed shape, mechanism, parts and drawing revision.','Function may need further testing and tooling samples.')])+'</div><div class="rs-sample__split">'+photo_block('/media/group/oem-sampling.webp','Buyer order and sample planning paperwork','Sample and quotation preparation')+'<div><h3>What to Check When the Sample Arrives</h3><ul><li>Model code, dimensions, nominal capacity and weight</li><li>Fit of lid, seal, straw and carry components</li><li>Markings, colors, logo position and print condition</li><li>Applicable food-contact information and required tests</li><li>Retail package, barcode, carton size and protection</li><li>Any deviation from approved drawings or renderings</li></ul></div></div></div></section>'
 sample_groups=[c for c in DATA['categories'] if c['id']=='samples']
 s+='<section class="rs-section"><div class="shell">'+heading('SAMPLE QUESTIONS','Before You Authorize Production')+question_groups(sample_groups)+'<p class="rs-disclaimer">Sample costs, production lead times and shipping arrangements are quoted for each requested SKU.</p></div></section>'
 return s+footer_cta('Prepare a Sample Brief','Give the model number, destination, buyer application, decoration details and intended bulk quantity.')
