 s+='<section class="rs-section"><div class="shell">'+heading('CUSTOM OPTIONS','What You Can Discuss Before Quoting','XUYI plastic bottle product photography. Decoration and structure are always evaluated by exact SKU.')+'<div class="rs-cap__list">'+''.join('<article><div>'+photo(im,title)+'</div><div><span>'+n+'</span><h3>'+e(title)+'</h3><p>'+e(desc)+'</p><a href="'+url+'">Explore this capability ↗</a></div></article>' for n,title,desc,url,im in options)+'</div></div></section>'
 s+='<section class="rs-section rs-section--dark"><div class="shell">'+heading('DECISION FRAMEWORK','OEM Branding vs. New Product Development','A clear distinction between the two scopes prevents unexpected tooling costs and sample changes.')+'<div class="rs-cap__compare"><article><h3>Existing-model OEM</h3><ul><li>Choose a current plastic model, body and lid configuration</li><li>Discuss logo, color, graphics, box and quantity</li><li>Confirm feasibility on a decorated physical sample</li><li>Agree approved version and carton specification</li></ul></article><article><h3>New-design ODM</h3><ul><li>Provide drawings, reference dimensions and use case</li><li>Review body and component engineering constraints</li><li>Assess tooling, prototypes and intellectual-property terms</li><li>Test and approve the production-representative sample</li></ul></article></div></div></section>'
 s+='<section class="rs-section"><div class="shell">'+heading('BUYER HANDOFF','What to Include in an OEM / ODM RFQ')+'<div class="rs-cap__rfq"><div><h3>Product and design</h3><p>Model or sketches, volume, material and lid requirements, dimensions and target users.</p></div><div><h3>Artwork and variants</h3><p>Vector logo, color references, carton layout, quantities per variation and sample expectations.</p></div><div><h3>Compliance and delivery</h3><p>Destination market, documents, test scope, packing list, preferred shipping term and timeline.</p></div></div><div class="rs-cap__resources">'+grid_links(LINKS)+'</div></div></section>'
 return s+footer_cta('Turn Your Bottle Idea Into an Approved Brief','Send your existing model or technical requirements; decoration, tools, samples and production timing can then be evaluated.')